(window.LADDER_CARDS=window.LADDER_CARDS||{})["41a"]=[{"q": "A configuration is not in a stop state. How many next configurations does it have?", "a": "exactly one", "w": ["none", "two", "as many as the marks"], "why": "The one-next technique: δ is a function of the pair (q, s)."}, {"q": "How much of the tape does one step of a tape machine read?", "a": "one cell", "w": ["the whole tape", "the input", "two cells"], "why": "The head reads only the cell it is on."}, {"q": "A machine stops in yes on members of A and may run for ever elsewhere. What does it do to A?", "a": "lists it", "w": ["decides it", "computes it", "refutes it"], "why": "Listing allows never stopping off the set."}, {"q": "A and the strings outside A are both listed. Which technique gives a decider?", "a": "both-sides", "w": ["tracks", "one-next", "one-search"], "why": "Run the two listers in turns; one of them stops."}, {"q": "A machine with k tapes takes t steps. About how many does one tape need?", "a": "t(n + t)", "w": ["t", "kt", "2ᵗ"], "why": "The tracks technique: two sweeps over at most n + t cells per old step."}, {"q": "The claim that tape machines compute whatever a person following techniques can compute is a…", "a": "thesis", "w": ["technique", "axiom", "law"], "why": "One side, following techniques, was never made exact."}, {"q": "Which green box of rung 41 holds the thesis?", "a": "loose, then locked", "w": ["laws with a known exception rate", "held in trust", "either way"], "why": "The loose word recipe is locked to the tape machine."}, {"q": "A lister has run a million steps on w without stopping. What follows about w?", "a": "nothing yet", "w": ["w is outside the set", "w is in the set", "the set is not listed"], "why": "It may stop at the next step."}, {"q": "Without the thesis, what does 41d still prove?", "a": "no tape machine decides stopping", "w": ["no recipe decides stopping", "nothing", "that minds outrun machines"], "why": "The thesis turns the claim about tape machines into one about recipes."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41b"]=[{"q": "Which of the three ways of building functions can make a machine that never stops?", "a": "search", "w": ["putting inside", "recursion", "the picks"], "why": "The least y may never come."}, {"q": "How many searches does any built function need?", "a": "one", "w": ["none", "as many as it was built with", "two"], "why": "The one-search technique: search for the first stopped step."}, {"q": "Which flag of 38h does the search-graph technique close?", "a": "Proof and Sub as formulas of the right shape", "w": ["the provable mark’s third property", "Con", "truth inside"], "why": "Tape-machine graphs are search formulas, reached by PA when true."}, {"q": "What does λn.λf.λx. f(n f x) do to the numeral of n?", "a": "gives the numeral of n + 1", "w": ["gives 2n", "gives n again", "has no finished form"], "why": "The numeral-iterator technique."}, {"q": "What is held in trust in the equal-reach technique?", "a": "leftmost feeding finds a finished term whenever any order does", "w": ["that terms can be coded", "that numerals exist", "that feeding stops"], "why": "The basement names it."}, {"q": "Before feeding y to λx.λy. x, what must be done?", "a": "rename the bound y", "w": ["nothing", "feed x first", "drop the λ"], "why": "Otherwise y is caught and the constant becomes the identity."}, {"q": "Which term has no finished form?", "a": "(λx. x x)(λx. x x)", "w": ["λx. x", "λf.λx. f x", "λx.λy. x"], "why": "Its only move gives itself again."}, {"q": "Three accounts reaching the same functions is evidence for what?", "a": "the thesis", "w": ["the stopping set is decided", "P equals NP", "the axiom of choice"], "why": "Agreement of independent exact accounts."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41c"]=[{"q": "How are the rows of a code separated?", "a": "by 11", "w": ["by 1", "by 00", "by #"], "why": "Single 1s separate blocks within a row."}, {"q": "Is whether a string is the code of some machine decided?", "a": "yes", "w": ["no", "only listed", "only for short strings"], "why": "The table-code technique: a finite check."}, {"q": "U runs M on w. What does U’s table depend on?", "a": "nothing about M", "w": ["M’s states", "w’s length", "M’s marks"], "why": "U’s table is fixed; M is written on its tape."}, {"q": "One step of M costs U a number of steps bounded by…", "a": "the length of ⟨M⟩ and of a cell", "w": ["the step count t", "nothing", "2ᵗ"], "why": "Walk to the row, copy three blocks."}, {"q": "38j’s fetch-and-run loop is which machine?", "a": "the universal machine", "w": ["the stopping decider", "a pattern machine", "a stack machine"], "why": "The program is data in the same memory."}, {"q": "Why are there questions no machine answers?", "a": "machines can be listed and sets of numbers cannot", "w": ["machines are too slow", "the stopping set is large", "U has too few states"], "why": "The few-machines technique, 35c’s diagonal."}, {"q": "Does the few-machines technique name a question with no machine?", "a": "no", "w": ["yes, stopping", "yes, PA’s reach", "yes, equations"], "why": "It counts; 41d names one."}, {"q": "Which rung 0 axiom does U spend and not earn?", "a": "anything can be written in a logical system", "w": ["either way", "choice", "the thesis"], "why": "U needs the thing written first."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41d"]=[{"q": "What is the stopping set H?", "a": "the strings ⟨M⟩ # w with M stopping on w", "w": ["the machines that stop on every input", "the codes of machines", "the strings M prints"], "why": "Its accepted name is the halting problem."}, {"q": "Is H listed?", "a": "yes", "w": ["no", "only its outside", "only for short codes"], "why": "Run U, and say yes when it stops."}, {"q": "E, fed ⟨M⟩, does what with D’s prediction about M on ⟨M⟩?", "a": "the opposite", "w": ["the same", "nothing", "asks again"], "why": "Loops on yes, stops on no."}, {"q": "Which earlier diagonal does 41d2 repeat?", "a": "35b’s unlisted real", "w": ["37k’s truth", "4l’s falling measure", "1e’s tables"], "why": "Stops plays the part of a digit."}, {"q": "Is the outside of H listed?", "a": "no", "w": ["yes", "only by U", "only with coins"], "why": "Both halves listed would make H decided."}, {"q": "Is “M stops on w within t steps” decided?", "a": "yes", "w": ["no", "only listed", "only if t is small"], "why": "Run U for t steps."}, {"q": "Does no-stop-decider say some pair M, w can never be settled by anyone?", "a": "no", "w": ["yes", "only for long codes", "only with the thesis"], "why": "No single machine is right on every pair."}, {"q": "A machine with a free answer to H fails to decide what?", "a": "stopping for machines with that free answer", "w": ["nothing", "H", "the empty set"], "why": "The same diagonal, one level up."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41e"]=[{"q": "A reduces to B and A is not decided. What follows?", "a": "B is not decided", "w": ["B is decided", "A is listed", "nothing"], "why": "The reduction-carries technique, turned round."}, {"q": "A is decided and reduces to B. What follows about B?", "a": "nothing", "w": ["B is decided", "B is not decided", "B is listed"], "why": "Reductions carry deciders from B to A only."}, {"q": "Does any machine decide whether a machine stops on every input?", "a": "no", "w": ["yes", "only for short codes", "only with coins"], "why": "The behaviour technique: a property of what machines do."}, {"q": "Is “the table has five rows” decided?", "a": "yes, by counting", "w": ["no, by the behaviour technique", "only listed", "no one knows"], "why": "It is about the text, not the behaviour."}, {"q": "Which two facts make σ_{M,w} reached by PA exactly when M stops?", "a": "true search statements are reached; only truths are reached", "w": ["PA is complete; PA is clash-free", "Con; U", "choice; induction"], "why": "Search-reached (38g4) and truth in ℕ (38g2)."}, {"q": "Solvable whole-number equations are listed. What did 1970 add?", "a": "every listed set is a solvability question", "w": ["they are decided", "they are fast", "none are solvable"], "why": "So stopping reduces to solvability."}, {"q": "x² + y² = 3 has no whole-number solution. Why?", "a": "squares leave 0 or 1 by 4", "w": ["3 is prime", "x and y are odd", "the search ran long"], "why": "A sum of two leaves 0, 1 or 2."}, {"q": "Is “M stops on some input within 100 steps” decided?", "a": "yes", "w": ["no, by the behaviour technique", "only listed", "only for M with 100 states"], "why": "Only inputs of length at most 100 matter."}, {"q": "Does the reach-undecided technique close every hope of settling disputes by calculating?", "a": "no, only a recipe for every statement", "w": ["yes, all of them", "it closes none", "only for physics"], "why": "Finite checks are still settled by calculating."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41f"]=[{"q": "What does A, the first half of SELF, do?", "a": "writes B’s code and stops", "w": ["writes its own code", "reads the tape", "runs B"], "why": "A = P_⟨B⟩."}, {"q": "What does B do with the code it reads?", "a": "writes the code of a printer of it in front", "w": ["erases it", "runs it", "copies it twice"], "why": "q turns a string into a printer of it."}, {"q": "Why can no machine’s table hold a copy of its own code?", "a": "the code is longer than any table holding it", "w": ["codes cannot be read", "machines cannot write", "U forbids it"], "why": "SELF makes A’s code from B’s."}, {"q": "The own-code technique gives R that does what T does on…", "a": "⟨R⟩ # w", "w": ["w alone", "⟨T⟩ # w", "⟨U⟩ # w"], "why": "R = A B T."}, {"q": "Which step of rung 38 does the own-code technique match?", "a": "the self-statement technique", "w": ["the one-reading technique", "the countable-world technique", "the proof-check technique"], "why": "Describe, then feed the description to itself."}, {"q": "Can a machine list endlessly many shortest machines?", "a": "no", "w": ["yes", "only short ones", "only with coins"], "why": "The shortest-unlisted technique."}, {"q": "Are there endlessly many shortest machines?", "a": "yes", "w": ["no", "exactly one", "none"], "why": "At least one for each computed function."}, {"q": "In s='s=%r;print(s%%s)';print(s%s), which part plays A?", "a": "the string s", "w": ["print(s%s)", "%r", "the semicolon"], "why": "s is the quotation; the print fills its gap."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41g"]=[{"q": "What is a pattern?", "a": "a set checked by a machine with no memory", "w": ["a set checked by a stack machine", "any listed set", "a set with a short certificate"], "why": "Its accepted name is a regular language."}, {"q": "Are and, or and not of patterns patterns?", "a": "yes", "w": ["only and", "only or", "no"], "why": "The joined-machines technique: pairs of states."}, {"q": "Pumping with q states: how long may xy be?", "a": "at most q letters", "w": ["any length", "exactly q", "at least q"], "why": "The repeat comes within the first q letters."}, {"q": "Who chooses the cut xyz in a proof that a set is no pattern?", "a": "the machine", "w": ["the proof", "the reader", "the shortest one"], "why": "The proof must defeat every allowed cut."}, {"q": "Is the set of strings of square length a pattern?", "a": "no", "w": ["yes", "only for short strings", "only with a stack"], "why": "q² + k falls between two squares."}, {"q": "Which family holds aⁿbⁿ but not aⁿbⁿcⁿ?", "a": "the second, stack machines", "w": ["the first", "the third", "the fourth"], "why": "The two-loop technique rules out aⁿbⁿcⁿ."}, {"q": "A machine never uses more than r cells. Is its stopping decided?", "a": "yes", "w": ["no", "only listed", "only if r is 1"], "why": "Bounded-room: q · r · mʳ configurations."}, {"q": "Two stacks are as strong as what?", "a": "a tape", "w": ["one stack", "a pattern machine", "nothing"], "why": "One stack each side of the head."}, {"q": "A set pumps for every member. Is it a pattern?", "a": "not necessarily", "w": ["yes", "no, never", "only if finite"], "why": "{aⁱbʲcᵏ : i = 0 or j = k} pumps and is no pattern."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41h"]=[{"q": "When is a set fast?", "a": "decided within nᵏ steps for a fixed k", "w": ["decided at all", "listed", "decided within 2ⁿ"], "why": "The class P."}, {"q": "Does the number of tapes change which sets are fast?", "a": "no", "w": ["yes", "only for two tapes", "only for NP"], "why": "The power-stays technique."}, {"q": "What is a certificate?", "a": "a short string that a fast checker accepts", "w": ["a proof of no", "a decider", "a listing"], "why": "At most a power of the length."}, {"q": "What certificate puts satisfiability in NP?", "a": "a true row", "w": ["the whole table", "a proof of no row", "a colouring"], "why": "Checked in one pass."}, {"q": "Every set in NP fast-reduces to which set?", "a": "the satisfiable statements", "w": ["the stopping set", "the patterns", "the primes"], "why": "The tableau technique."}, {"q": "Why are 2 × 3 windows enough in the tableau?", "a": "each cell is fixed by the three above", "w": ["the table is small", "rows are short", "the checker is fast"], "why": "The one-next technique."}, {"q": "Why does the more-time technique pad its input?", "a": "so U has time to simulate M", "w": ["to hide the code", "to make it fast", "to make it a pattern"], "why": "c nᵏ < nᵏ⁺¹ once n is large."}, {"q": "Room for reaching among N states by halving?", "a": "about (log₂ N)² times one state", "w": ["N", "log₂ N", "2ᴺ"], "why": "The halving-room technique."}, {"q": "Can the diagonal tell P from NP?", "a": "no", "w": ["yes", "only for small k", "only with coins"], "why": "It works the same with any free question."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41i"]=[{"q": "A set is in BPP when a fast coin machine is wrong with chance at most…", "a": "1/3 on every input", "w": ["1/3 on most inputs", "1/2", "0"], "why": "The chance holds input by input."}, {"q": "k runs, answered by majority. The majority-vote bound?", "a": "8/k", "w": ["2⁻ᵏ", "1/3ᵏ", "k/8"], "why": "The spread-bound technique of 30h."}, {"q": "Which green box of rung 41 is in 41i?", "a": "laws with a known exception rate", "w": ["loose, then locked", "held in trust", "either way"], "why": "The chance of error is fixed in advance."}, {"q": "Nonzero p of degree d, letters drawn from s numbers. Chance p is 0?", "a": "at most d/s", "w": ["at most 1/s", "exactly d/s", "at least d/s"], "why": "The random-point technique."}, {"q": "Which technique of rung 25 starts the random-point proof?", "a": "the root technique", "w": ["the spread-bound technique", "the tableau technique", "the product-keeper"], "why": "At most d roots."}, {"q": "AB ≠ C, r random 0s and 1s. Chance A(Br) = Cr?", "a": "at most 1/2", "w": ["at most 1/n", "exactly 1/2", "at most 1/3"], "why": "The random-column technique."}, {"q": "Is every set in BPP in PSPACE?", "a": "yes", "w": ["no", "only fast ones", "unknown"], "why": "Try every coin string in the same room."}, {"q": "Do coins let a machine decide the stopping set?", "a": "no", "w": ["yes", "only with many coins", "unknown"], "why": "Run every coin string: no chance left."}, {"q": "p was 0 at ten random points. What is shown?", "a": "a stated chance of error, not a proof", "w": ["p is zero", "p is not zero", "nothing"], "why": "At most (d/s)¹⁰."}, {"q": "Each of k runs is wrong with chance at most 1/3. The fast-fall technique bounds the majority's error by?", "a": "(2√2/3)ᵏ", "w": ["8/k", "(1/3)ᵏ", "1/k²"], "why": "The stray bound on 2^W."}, {"q": "About how many runs bring the majority's error below one in a million, by the fast-fall technique?", "a": "235", "w": ["8 million", "20", "3"], "why": "0.943ᵏ < 10⁻⁶."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41j"]=[{"q": "How many steps does the two-state champion take?", "a": "6", "w": ["4", "21", "14"], "why": "BB(2) = 6, with four 1s."}, {"q": "A configuration is seen twice in a run. What follows?", "a": "the machine never stops", "w": ["it stops next", "nothing", "it is a pattern"], "why": "Back-again with the one-next technique."}, {"q": "Same state, fresh blank tape, further right, never stepping left of the first. What follows?", "a": "it never stops", "w": ["it stops", "it repeats a configuration", "nothing"], "why": "The blank-march technique."}, {"q": "A machine with q states never steps left. Within how many steps does a stopper stop?", "a": "n + q", "w": ["q", "2ⁿ", "nq"], "why": "The one-way technique."}, {"q": "What does E differ from each machine of the table at?", "a": "that machine’s own column", "w": ["the first column", "every column", "no column"], "why": "The flip-diagonal technique."}, {"q": "1000 steps, no repeat. Does the machine never stop?", "a": "not shown", "w": ["yes", "no, it stops", "it is a pattern"], "why": "It may stop at step 1001."}, {"q": "A0 → 1RB, A1 → 1R stop, B0 → 0RC, B1 → 1RB, C0 → 1LC, C1 → 1LA: steps on a blank tape?", "a": "14", "w": ["21", "6", "it never stops"], "why": "Six 1s; BB(3) = 21 is another machine."}, {"q": "Is there a one-state machine that stops after more than one step?", "a": "no", "w": ["yes", "only on a two-way tape", "unknown"], "why": "Otherwise it reads a fresh blank for ever."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41k"]=[{"q": "a ∨ b ∨ c ∨ d is split as…", "a": "(a ∨ b ∨ z) ∧ (¬z ∨ c ∨ d)", "w": ["(a ∨ b ∨ z) ∧ (z ∨ c ∨ d)", "(a ∨ b) ∧ (c ∨ d)", "a ∧ b ∧ c ∧ d"], "why": "The clause-split technique."}, {"q": "In the palette, x and x̄ take which colours?", "a": "those of T and F, one each", "w": ["both of B", "any two", "the same"], "why": "Both linked to B and to each other."}, {"q": "Or-piece, both inputs false. What is o?", "a": "false", "w": ["true", "spare", "either"], "why": "u and v take true and spare."}, {"q": "Or-piece, an input true. What can o be?", "a": "true, by some finishing", "w": ["only false", "only spare", "nothing"], "why": "Some finishing allows o true."}, {"q": "Dots of the map for n letters and m clauses?", "a": "3 + 2n + 6m", "w": ["3 + 3n + 12m", "2n + 6m", "3nm"], "why": "Links are 3 + 3n + 12m."}, {"q": "Why is the reduction fast though the map has 3²⁷ colourings?", "a": "it only writes the map", "w": ["it tries them in parallel", "it uses coins", "it is not fast"], "why": "One pass along the statement."}, {"q": "With two colours, which piece fails?", "a": "the palette triangle", "w": ["the or-piece only", "nothing", "the clause split"], "why": "A triangle needs three colours."}, {"q": "Clauses to say a map has a three-colouring, d dots and l links?", "a": "4d + 3l", "w": ["3d + 3l", "d + l", "9dl"], "why": "d at-least-one, 3e at-most-one, 3l per link."}, {"q": "Why is 34m’s knot colouring count quick?", "a": "its technique is a sum technique, solved by elimination", "w": ["knots are small", "it uses coins", "it is not quick"], "why": "Labels adding to a multiple of 3."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["41l"]=[{"q": "Two maps not the same shape. How often does the prover name the shuffled one?", "a": "every time", "w": ["half the time", "never", "a third of the time"], "why": "With unlimited time it finds i."}, {"q": "Same shape: the prover’s chance of being right each round?", "a": "exactly 1/2", "w": ["1", "0", "1/3"], "why": "What it sees does not depend on i."}, {"q": "When must the colours be locked?", "a": "before the checker picks a link", "w": ["after the pick", "never", "at the end"], "why": "Else the prover picks colours to suit."}, {"q": "No three-colouring, l links. Chance of being caught each round?", "a": "at least 1/l", "w": ["at least 1/2", "exactly 1/3", "0"], "why": "Some link has ends alike."}, {"q": "Why rename the colours every round?", "a": "otherwise rounds together show the colouring", "w": ["to speed it up", "to fool the checker", "it is not needed"], "why": "Fresh renaming keeps each pair random."}, {"q": "Each round the checker sees which of the 6 ordered pairs?", "a": "each with chance 1/6", "w": ["always the same pair", "the true colours", "none"], "why": "The self-made-record technique."}, {"q": "Can the checker’s record convince a judge?", "a": "no", "w": ["yes", "only after many rounds", "only with locks"], "why": "It could have made it alone."}, {"q": "Which techniques does the through-colouring technique pass through?", "a": "the tableau and map-from-clauses techniques", "w": ["the universal and stopping-listed techniques", "the pumping technique", "the random-point technique"], "why": "Any set in NP becomes a map."}, {"q": "What is held in trust in 41l2?", "a": "locked boxes, until rung 43", "w": ["the thesis", "choice", "that P differs from NP"], "why": "Built from functions believed slow to undo."}];
